        yield self
        for module in self.modules:
            yield from module

    def load(self, device: torch.Device):
        self.device = device
        for module in self.modules:
            module.load(device)

    def unload(self):
        self.device = None
        for module in self.modules:
            module.unload()

    def prepare_for_device(self, x: torch.Tensor, params: dict) -> torch.Tensor:
        if x.device != self.device:
            x = x.to(self.device)
